#!/usr/bin/env python3
"""Render final corrected UDP report tables from validated original-derived CSVs."""
import pathlib,csv,json,statistics,hashlib
BASE=pathlib.Path(__file__).resolve().parent;D=BASE/'comparison/corrected-udp';DOC=BASE.parents[1]/'docs/feature/netns-density-295/spike/kernel-vs-aya-benchmark.md'
def load(n):return list(csv.DictReader((D/n).open()))
summary=load('summary.csv');memory=load('resource-summary.csv');idle=load('idle-summary.csv');setup=load('setup-summary.csv');valid=json.loads((D/'native-validation.json').read_text());assert valid['completed_cohorts']==6 and not valid['checks_failed']
def condition(v,n,size,rate,active=None):return next(r for r in summary if r['kind']=='udp-open'and r['variant']==v and int(r['population'])==n and int(r['payload'])==size and int(r['target_per_s'])==rate and int(r['eligible_active'])==(n if active is None else active))
def fmt(r,m,d=3,scale=1):
 xs=[r.get(m+'_'+k)for k in ['median','min','max']]
 if not all(x not in [None,'']for x in xs):return '—'
 a,b,c=[float(x)*scale for x in xs];return f'{a:,.{d}f} [{b:,.{d}f}–{c:,.{d}f}]'
lines=['## Corrected UDP comparison: completed native evidence','', '**WORKS for the measured shared contract:** stock-kernel Aya forwarding of genuine empty and 0..59,000-byte IPv4 UDP messages, intact nonzero boundaries and identities, at 16,384 actual transport owners. No kernel patches, module assistance or userspace application-payload relay. The corrected directional candidate remains distinct from the frozen failing SEQPACKET candidate.','',f"Increment-r completed **six independent private VM cohorts**, AB/BA/AB: **384 valid open-loop windows**, 30 real-empty-message request/reply windows, 90 exact idle intervals and start/end live audits at all five populations. All six normal teardowns observed stock references **0 inside the live private kernel**. The separate executable receipt audit has zero failed checks. The native launcher took **{json.loads((BASE/'increment-r/evidence/retrieval-receipt.json').read_text())['wall_s']/60:.1f} minutes**, including build/bootstrap/retrieval. No production, design or DES files were changed by this benchmark; no commits were made.",'','### All 16,384 peers participating and simultaneously pending','', 'These unrestricted UDP conditions include the initial all-peer burst and four endpoint actor shards. Every window observed16,384 participating and16,384 maximum pending peers. Values are medians [min–max] across three independently provisioned cohorts. Throughput counts verified application bytes/datagrams in both directions. Tail latency describes delivered request/reply messages; the burst is part of this workload.','', '| Application bytes | Module delivered datagrams/s | Corrected Aya delivered datagrams/s | Module CPU µs/delivered datagram | Corrected Aya CPU µs/delivered datagram | Module p99 ms | Corrected Aya p99 ms |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
for size in [0,64,1431,59000]:
 a=condition('kernel',16384,size,0);b=condition('aya',16384,size,0);lines.append(f"| {size:,} | {fmt(a,'delivered_datagrams_per_s',0)} | {fmt(b,'delivered_datagrams_per_s',0)} | {fmt(a,'vm_cpu_us_per_delivered_datagram',1)} | {fmt(b,'vm_cpu_us_per_delivered_datagram',1)} | {fmt(a,'p99_us',1,.001)} | {fmt(b,'p99_us',1,.001)} |")
a=condition('kernel',16384,59000,0);b=condition('aya',16384,59000,0)
lines+=['',f"At59,000 bytes: module **{fmt(a,'application_GiB_per_s')}GiB/s**, **{fmt(a,'vm_mean_busy_cores',2)} busy cores**, **{fmt(a,'vm_core_seconds_per_delivered_GiB',2)}core-s/GiB**; corrected Aya **{fmt(b,'application_GiB_per_s')}GiB/s**, **{fmt(b,'vm_mean_busy_cores',2)} busy cores**, **{fmt(b,'vm_core_seconds_per_delivered_GiB',2)}core-s/GiB**. These are complete measured endpoint/kernel paths under the same four-vCPU budget, including codec and generator cost; they are not isolated proxy efficiencies or technology peaks.",'', 'All the tabled unrestricted all-peer conditions had zero counted deadline loss, corruption and boundary violations. Other saturation conditions did have missing deliveries at the cutoff, retained below. Empty open-loop messages have count/loss evidence and undefined latency; the separate ordinary empty-message request/reply windows retain actual latency samples.','', '### Allocated memory, idle and lifecycle at 16,384 UDP owners','', '| Component / operation | Module | Corrected Aya |','| --- | ---: | ---: |']
ma=next(r for r in memory if r['variant']=='kernel'and r['population']=='16384');mb=next(r for r in memory if r['variant']=='aya'and r['population']=='16384')
for title,m,scale,dec in [('Kernel SUnreclaim increase from loaded baseline, GiB','sunreclaim_delta_loaded_kib',1/1048576,3),('KernelStack increase, MiB','kernel_stack_delta_loaded_kib',1/1024,1),('Process PSS increase, MiB','pss_delta_loaded_kib',1/1024,1),('Process FDs','fds',1,0),('Process tasks, including stock vhost workers','self_tasks',1,0),('All private-kernel tasks','all_tasks',1,0)]:lines.append(f'| {title} | {fmt(ma,m,dec,scale)} | {fmt(mb,m,dec,scale)} |')
for v in ['kernel','aya']:
 pass
ia=next(r for r in idle if r['variant']=='kernel'and r['population']=='16384');ib=next(r for r in idle if r['variant']=='aya'and r['population']=='16384');lines.append(f"| Idle busy cores, nine exact intervals | {float(ia['busy_cores_median']):.3f} [{float(ia['busy_cores_min']):.3f}–{float(ia['busy_cores_max']):.3f}] | {float(ib['busy_cores_median']):.3f} observed [{float(ib['busy_cores_min']):.3f}–{float(ib['busy_cores_max']):.3f}] |")
sa=next(r for r in setup if r['variant']=='kernel'and r['population']=='16384');sb=next(r for r in setup if r['variant']=='aya'and r['population']=='16384');lines.append(f"| Activation of new12,288 owners while growing4,096→16,384, seconds | {fmt(sa,'setup_s',2)} | {fmt(sb,'setup_s',2)} |");lines.append(f"| New endpoints/s in that activation batch | {fmt(sa,'new_endpoints_per_s',0)} | {fmt(sb,'new_endpoints_per_s',0)} |")
ret=json.loads((D/'retirement.json').read_text())
def retfmt(v,event,key):
 vals=[r[key]for r in ret if r['run'].split('-')[1]==v and r['event']==event];return f'{statistics.median(vals):.2f} [{min(vals):.2f}–{max(vals):.2f}]'
lines.append(f"| Per-peer owned retirement, seconds | {retfmt('kernel','owned_retirement','duration_s')} | {retfmt('aya','owned_retirement','duration_s')} |");lines.append(f"| Live-zero proof elapsed from retirement start, seconds | {retfmt('kernel','transport_drain_live_kernel','retirement_total_s')} | {retfmt('aya','transport_drain_live_kernel','retirement_total_s')} |")
lines+=['','Memory components are separate native observations, never an invented combined total. Zero idle CPU is an observed100Hz tick delta, not literal zero execution. The live-zero receipt timer includes intermediate inventory/serialization; the per-peer control timer stops before that capture. Corrected Aya owns three occupied SockHash keys and two actual vsock connections per CID, **49,152 occupied keys at16,384**, while retaining one actual vhost FD/memory context/queue pair per CID. Its additional connection/map cost is included.','', '### Saturation loss, long queues and generator limits','', '| 59,000B, one active/held peer, target10,000 sends/s | Module | Corrected Aya |','| --- | ---: | ---: |']
a=condition('kernel',1,59000,10000);b=condition('aya',1,59000,10000)
for title,m,dec,scale in [('Actual sends/s over total measured traffic+delivery duration','sent_per_total_measured_s',0,1),('Not delivered host→guest by cutoff, datagrams','loss_host_guest',0,1),('Delivered-subset p99, ms','p99_us',1,.001)]:lines.append(f'| {title} | {fmt(a,m,dec,scale)} | {fmt(b,m,dec,scale)} |')
total=lambda k:sum(v[k]for v in valid['cohorts'])
lines+=['',f"Across all384 open windows: **{total('sent'):,} sent**, **{total('guest_delivered_by_cutoff'):,} delivered to guest consumers by cutoff**, **{total('app_delivered_by_cutoff'):,} delivered replies by cutoff**. Not-delivered-by-cutoff counts are **{total('deadline_loss_host_guest'):,} host→guest** and **{total('deadline_loss_guest_host'):,} guest→host**. These counts are not relabelled as corruption or erased. Late messages were validated during inter-window and post-population settling; its counts and separate whole-VM CPU are retained.",'','The common polling/service loop and byte-pattern generation consume much of the budget at some loads. In particular, a59,000-byte target can exceed actual generator rate. Goodput is actual verified delivery over the actual measured interval; load plots use actual sends over the full measured traffic+delivery duration, with target/declared pacing duration preserved separately. No unmatched baseline is subtracted as proxy CPU.','', '### Coverage and remaining limits','', '| Population | UDP open-loop payloads | Activity | Load axes | Independent pairs |','| ---: | --- | --- | --- | ---: |','| 1 / 64 | 0 / 64 / 1431 / 59000 | Whole eligible pool | 1000 / 10000 / unrestricted | 3 |','| 1024 / 4096 | 64 / 1431 | 64-peer subset and all-peer burst | 10000 / unrestricted | 3 |','| 16384 | 0 / 64 / 1431 / 59000 | 64-peer subset and all-peer burst | 10000 / 100000 / unrestricted | 3 |','', 'Allocated idle, memory, real binding/map/context counts, tagged start/end audits and empty-message request/reply samples cover all five populations. Intermediate0/59000 open-loop cells were not run. This does not claim the entire Cartesian matrix, full65507-byte UDP, IPv6, arbitrary multi-peer UDP-server behavior behind one CID, ordinary-guest-stack composition, incoming TCP/SSH, TLS or offloads. Module/BPF loader latency and global BPF teardown latency were not separately timed. Original c/e TCP three-window cohorts remain a separately scoped comparison, not three independent TCP VM pairs.','', '### Evidence and plots','', '- [Native receipt audit](../../../../spike-scratch/netns-density-295-kernel-vs-aya-benchmark/comparison/corrected-udp/native-validation.json)','- [Actual samples and all median/range tables](../../../../spike-scratch/netns-density-295-kernel-vs-aya-benchmark/comparison/corrected-udp/summary.csv)','- [Goodput versus whole-VM CPU](../../../../spike-scratch/netns-density-295-kernel-vs-aya-benchmark/comparison/corrected-udp/goodput-cpu.svg)','- [59,000-byte population/goodput/CPU/p99 plot](../../../../spike-scratch/netns-density-295-kernel-vs-aya-benchmark/comparison/corrected-udp/udp-59000-population.svg)','- [p95/p99 versus measured load at16,384](../../../../spike-scratch/netns-density-295-kernel-vs-aya-benchmark/comparison/corrected-udp/udp-59000-load-16384.svg)','- [Separate memory-component curves](../../../../spike-scratch/netns-density-295-kernel-vs-aya-benchmark/comparison/corrected-udp/memory-population.svg)','- [Late/control settling CPU](../../../../spike-scratch/netns-density-295-kernel-vs-aya-benchmark/comparison/corrected-udp/posttraffic-settle.csv)','- [Complete harness-cohort CPU scope](../../../../spike-scratch/netns-density-295-kernel-vs-aya-benchmark/comparison/corrected-udp/cohort-accounting.csv)','- [Traffic/idle/retired memory snapshots](../../../../spike-scratch/netns-density-295-kernel-vs-aya-benchmark/comparison/corrected-udp/memory-stages.csv)','', 'The final physical audit found no owned QEMU process or canonical lease owner and unchanged physical module/link inventories. Three retirement JSON events had an inserted module printk line on the shared UART: exact known console bytes were deinterleaved with raw/recovered hashes, strict JSON parsing and no numeric edits; originals remain intact. No unrecoverable UART events or failed comparison checks remain.','']
text='\n'.join(lines)
for a,b in [('observed16','observed 16'),('and16','and 16'),('At59','At 59'),('new12','new 12'),('growing4','growing 4'),('observed100','observed 100'),('at16','at 16'),('target10','target 10'),('all384','all 384'),('a59','a 59'),('Intermediate0','Intermediate 0'),('full65507','full 65507')]:text=text.replace(a,b)
(D/'highlights.md').write_text(text)
s=DOC.read_text();needle='## Preliminary matching TCP observations'
if '## Corrected UDP comparison: completed native evidence' in s:
 start=s.index('## Corrected UDP comparison: completed native evidence');end=s.index(needle,start);s=s[:start]+s[end:]
s=s.replace(needle,text+'\n'+needle);s=s.replace('**Status: corrected Aya UDP candidate passed the bounded native validation; matched all-population measurements are being rerun after a bounded outside-window fence repair. Not independently reviewed.**','**Status: corrected Aya UDP works for the measured contract; native comparison complete. Not independently reviewed.**')
s=s.replace('The affected matched measurements are being rerun with separate source\nprovenance; original-candidate results are not silently replaced.','The affected measurements were rerun in six independently provisioned private\nVMs with separate source provenance. Original-candidate results remain intact.')
s=s.replace('The full increment-r corrected matrix is running with frozen executable source\nfrom q, three independent AB/BA/AB pairs, and unchanged steady timer boundaries.','The full increment-r corrected matrix completed with frozen executable source\nfrom q, three independent AB/BA/AB pairs, and unchanged steady timer boundaries.')
s=s.replace('| r | Frozen corrected executable sources from q; full all-population AB/BA/AB matrix running. |','| r | Frozen sources from q; completed six full-population AB/BA/AB cohorts,384 valid open windows, all live reference-zero receipts and unchanged physical inventory. |')
DOC.write_text(s)
# Preserve the raw dispatcher defaults without mistaking them for the executed matrix.
receipt={'source':'original run-matrix.executed.json, each begin/native-result and original retrieval receipt','actual_matrix':json.loads((BASE/'increment-r/evidence/run-matrix.executed.json').read_text()),'actual_completed_cohorts':6,'actual_maximum_population_each':16384,'all_native_passed':True,'raw_result_default_metadata_note':'result.json maximum64/order fields reflect CLI defaults when --matrix is used; they are not executed matrix metadata. Originals unchanged.','original_retrieval':json.loads((BASE/'increment-r/evidence/retrieval-receipt.json').read_text())};(D/'matrix-completion-receipt.json').write_text(json.dumps(receipt,indent=2))
print(json.dumps({'report':str(DOC),'source_groups':len(summary),'cohorts':6,'open_windows':384}))
